(ns babashka.fs
  "babashka.fs API over cljc's fs.clj battery (filesystem via libc FFI).")
(cljc/in-ns* nil)
(load-file "fs.clj")
(cljc/in-ns* "babashka.fs")
(def exists?      fs/exists?)
(def directory?   fs/directory?)
(def regular-file? fs/regular-file?)
(def list-dir     fs/list-dir)
(def create-dir   fs/create-dir)
(def create-dirs  fs/create-dir)
(def delete       fs/delete)
(def move         fs/move)
(def copy         fs/copy)
(def file-name    fs/file-name)
(def parent       fs/parent)
(def extension    fs/extension)
(def cwd          fs/cwd)
(def temp-dir     fs/temp-dir)
